package com.example.carbonai.dtos;

import java.util.List;

/**
 * This DTO represents the final JSON payload that the backend sends to the frontend.
 * It contains both the raw data needed to draw the charts (progress bars, summary cards)
 * AND the final text generated by the AI.
 */
public record TripAnalysisResponse(
    int distanceKm,
    double lowestCo2,
    double highestCo2,
    List<ModeDetails> modes,
    String aiRecommendation
) {
    /**
     * A nested record representing the specific data for a single transport mode 
     * (e.g., Bus, Train, Plane) to be displayed in the frontend progress bars.
     */
    public record ModeDetails(
        String name,
        double co2,
        String time,
        String cost
    ) {}
}
